{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table babygo-wh.maplemonk.babygo_returns_consolidated as select e.reference_code ,e.saleorderitemcode ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCT_NAME_final) AS PRODUCT_NAME ,e.SKU ,e.sku as commonsku ,UPPER(e.product_category) AS product_category ,UPPER(e.product_sub_category) AS product_sub_category ,e.quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.name AS NAME ,e.email AS EMAIL ,cast(null as string) as return_request_number ,cast(return_initiated_date as datetime) as original_return_request_date ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'Approved\' else null end as return_approval_status ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r.seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.Return_Type) like \'%customer%\' then \'return\' when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'return\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' when lower(r.seller_return_reason) is not null then \'return\' else null end as return_request_type , case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r. seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.Return_Type) like \'%customer%\' then \'return\' when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'return\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' when lower(r.seller_return_reason) is not null then \'return\' else null end as return_type ,coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) as return_flag ,coalesce(r.RETURNED_QUANTITY, e.RETURNED_QUANTITY) as TOTAL_RETURNED_QUANTITY ,coalesce(r.channel_return_reason,r.seller_return_reason) as return_reason ,e.Payment_mode ,e.selling_price ,coalesce(r.PRODUCT_NAME, case when e.return_flag = 1 then e.PRODUCT_NAME_final end) as returned_product_name ,coalesce(r.style_id, case when e.return_flag = 1 then e.style_id end) as style_id ,coalesce(r.lot, case when e.return_flag = 1 then e.lot end) as lot ,coalesce(r.sku, case when e.return_flag = 1 then e.commonsku end) as returned_sku ,coalesce(r.Total_Credit_Note_Amount, e.returned_sales) as TOTAL_RETURN_AMOUNT ,case when e.return_flag = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,null as TOTAL_RETURN_AMOUNT_EXCL_TAX ,coalesce(r.saleorderitemcode, case when e.return_flag = 1 then e.saleorderitemcode end) as returned_item_saleorderitemcode ,e.order_status as oms_order_status ,CASE WHEN e.pincode LIKE \'1%\' OR e.pincode LIKE \'2%\' THEN \'North Region\' WHEN e.pincode LIKE \'3%\' OR e.pincode LIKE \'4%\' THEN \'West Region\' WHEN e.pincode LIKE \'5%\' OR e.pincode LIKE \'6%\' THEN \'South Region\' WHEN e.pincode LIKE \'7%\' OR e.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,DATE_DIFF(date(return_initiated_date), date(Delivered_Date), DAY) AS days_from_delivery ,\'BabyGo\' as brand ,concat(\'<img src=\"\',pm.product_image_url,\'\"width=\"70\">\') as image ,fk.return_type as flipkart_return_type from maplemonk.babygo_wh_sales_consolidated e left join maplemonk.babygo_wh_easyecom_returns_intermediate r on e.reference_code = r.reference_code and e.saleorderitemcode = r.saleorderitemcode left join ( select * from maplemonk.EasyEcom_Easyecom_BabyGo_product_master qualify row_number() over (partition by sku order by 1) = 1 ) pm on pm.sku = e.commonsku left join ( select order_id, return_id, order_item_status, return_reason, return_sub_reason, CASE WHEN LOWER(return_reason) IN ( \'size fit issues\', \'quality issues\', \'quality issue\', \'customer remorse\', \'customer requested\', \'multiple issues with product\', \'damaged product\', \'missing item\', \'damage\', \'not received\', \'return cancelled\', \'order cancelled\', \'cancelled by client\', \'cancelled by client over api\', \'cancelled otp validated\', \'order cancelled by seller support\', \'mp cancellation\', \'shield cancellation\', \'whatsapp\', \'orc validated with customer\', \'orc validated with custo\' ) THEN \'customer_return\' WHEN LOWER(return_reason) IN ( \'customer rejection\', \'rejected by customer\', \'return to origin\', \'rto notified\', \'aged beyond limit\', \'shipment eob ageing\', \'misshipment\', \'seller did not handover\', \'attempts exhausted\', \'shipment unattended\', \'not serviceable\', \'uncontrollable factors\', \'damaged shipment obd\', \'curfew/strike\', \'other state misroute\', \'upstream shipment eob ageing\', \'damaged shipment\', \'brsnr\', \'shipmentintransitbyondlimit\', \'hub non functional\', \'no otp for obd\', \'smart pickup check override\', \'supply chain issues\', \'shipment lost\', \'client instructions for rto\', \'shipment delayed\', \'vendor status not configured\', \'returned as per security instructions\', \'max ivr attempts exhausted\', \'rton\', \'rto due to embargo\' ) THEN \'courier_return\' END AS return_type from maplemonk.babygo_flipkart_order_fulfilment_fact_items where order_item_status LIKE \'%RETURN%\' ) fk on fk.order_id = e.order_id ; CREATE OR REPLACE TABLE babygo-wh.maplemonk.babygo_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and lower(return_request_type) = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM babygo-wh.maplemonk.babygo_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(original_return_request_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM babygo-wh.maplemonk.babygo_returns_consolidated WHERE return_flag = 1 and lower(return_request_type) = \'return\' and original_return_request_date is not null GROUP BY return_month,return_date,marketplace ), rto as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_rto_items_received_in_month, count(distinct reference_code) as rto_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as rto_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_rto_sales FROM babygo-wh.maplemonk.babygo_returns_consolidated WHERE return_flag = 1 and lower(return_request_type) = \'rto\' and original_return_request_date is not null GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, rto.total_rto_items_received_in_month, rto.rto_orders_received_in_month, rto.rto_quantity_received_in_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month, from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace LEFT JOIN rto ON rto.return_date = o.order_date and rto.marketplace = o.marketplace order by order_date desc ;",
                    "transaction": true
                }
            ) }}
